insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('agent-b-private','agent-b-private',false,10485760,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain','text/markdown','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','image/png','image/jpeg','image/webp']) on conflict (id) do nothing;
create table if not exists public.agent_b_file_references(object_id text primary key, discovery_id uuid not null references public.agent_b_discoveries(discovery_id) on delete restrict, path text not null, file_type text not null, byte_size bigint not null check(byte_size>0 and byte_size<=10485760), sha256 text not null, created_at timestamptz not null);
alter table public.agent_b_file_references enable row level security; revoke all on table public.agent_b_file_references from public,anon,authenticated,service_role; grant select on public.agent_b_file_references to authenticated;
create policy agent_b_file_owner_read on public.agent_b_file_references for select to authenticated using(exists(select 1 from public.agent_b_discoveries d join public.agent_b_discovery_access a using(discovery_id) where d.discovery_id=agent_b_file_references.discovery_id and d.owner_id=auth.uid() and a.identity_id=auth.uid() and a.role='OWNER'));
create policy agent_b_storage_owner on storage.objects for all to authenticated using(bucket_id='agent-b-private' and exists(select 1 from public.agent_b_discoveries d join public.agent_b_discovery_access a on a.discovery_id=d.discovery_id where d.discovery_id=split_part(name,'/',1)::uuid and d.owner_id=auth.uid() and a.identity_id=auth.uid() and a.role='OWNER')) with check(bucket_id='agent-b-private' and exists(select 1 from public.agent_b_discoveries d join public.agent_b_discovery_access a on a.discovery_id=d.discovery_id where d.discovery_id=split_part(name,'/',1)::uuid and d.owner_id=auth.uid() and a.identity_id=auth.uid() and a.role='OWNER'));
